    const live_stream_ref01_markdef_up0 = { name: 'active_asset_id', value: 'Mark01-live_stream_ref01_' + setup.now }
    ;(live_stream_ref01_data_up0 as any)[live_stream_ref01_markdef_up0.name] = live_stream_ref01_markdef_up0.value

    const live_stream_ref01_resdata_up0 = (await live_stream_ref01_ent.update(live_stream_ref01_data_up0)).data()
    assert(live_stream_ref01_resdata_up0.id === live_stream_ref01_data_up0.id)

    assert((live_stream_ref01_resdata_up0 as any)[live_stream_ref01_markdef_up0.name] === live_stream_ref01_markdef_up0.value)


    // LOAD
    const live_stream_ref01_match_dt0: any = {}
    live_stream_ref01_match_dt0.id = live_stream_ref01_data.id
    const live_stream_ref01_data_dt0 = (await live_stream_ref01_ent.load(live_stream_ref01_match_dt0)).data()
    assert(live_stream_ref01_data_dt0.id === live_stream_ref01_data.id)


    // REMOVE
    const live_stream_ref01_match_rm0: any = { id: live_stream_ref01_data.id }
    await live_stream_ref01_ent.remove(live_stream_ref01_match_rm0)
  

    // LIST
