    const live_stream_ref01_list_rt0 = (await live_stream_ref01_ent.list(live_stream_ref01_match_rt0)).map((e: any) => e.data())

    assert(isempty(select(live_stream_ref01_list_rt0, { id: live_stream_ref01_data.id })))


